import React from 'react';

const About: React.FC = () => {
  return (
    <div className="about">
      <h1>О проекте</h1>
      <div className="about-content">
        <p>
          Это бета-версия системы для автоматического обнаружения и цензурирования 
          персональных данных на изображениях.
        </p>
      </div>
    </div>
  );
};

export default About;
